package com.kuaixietech.insurance;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.kuaixietech.security.DomainAccessGuard;
import com.kuaixietech.service.trading.support.IntentPricing;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.kuaixietech.insurance.InsuranceModels.*;
class InsuranceSafetyTest {
 Product product(){return new Product("cargo","picc","Insurer","Cargo","transport","native","P01","PICC_MAIN","https://insurer.example/terms","https://insurer.example/exclusions","https://insurer.example/claims",Set.of("insurer.example"),Set.of("pay.insurer.example"),true,1);}
 PolicyReceipt receipt(String app,String order,String currency,BigDecimal premium,boolean direct){return new PolicyReceipt("provider-app",app,order,"picc","P01","active","policy","coverage",new BigDecimal("1000.00"),premium,currency,direct,"terms-v1",Instant.now().minusSeconds(1),Instant.now().plusSeconds(3600),"https://insurer.example/policy");}
 Map<String,Object> application(){return new HashMap<>(Map.of("id","app","provider_application_ref","provider-app","order_id","order","quote_id","quote","status","awaiting_provider"));}
 Map<String,Object> quote(){return new HashMap<>(Map.of("currency","CNY","terms_version","terms-v1","declared_value",new BigDecimal("1000.00"),"premium",new BigDecimal("8.50")));}
 @Test void newOrderDoesNotCreatePlatformPremiumOrGuarantee(){var p=IntentPricing.externalQuote(new BigDecimal("1000"),"yes");assertEquals(new BigDecimal("1050.00"),p.buyerEscrow());assertEquals(new BigDecimal("0.00"),p.insurancePremium());assertEquals(new BigDecimal("200.00"),p.vendorDeposit());assertTrue(IntentPricing.isEscrowVersion(p.pricingVersion()));assertEquals(new BigDecimal("10.00"),IntentPricing.quote(new BigDecimal("1000"),"yes").insurancePremium());}
 @Test void invalidOrMismatchedReceiptsNeverVerifyCoverage(){for(var r:List.of(receipt("another-app","order","CNY",new BigDecimal("8.50"),true),receipt("app","other-order","CNY",new BigDecimal("8.50"),true),receipt("app","order","USD",new BigDecimal("8.50"),true),receipt("app","order","CNY",new BigDecimal("9.00"),true),receipt("app","order","CNY",new BigDecimal("8.50"),false)))assertThrows(IllegalArgumentException.class,()->InsuranceTransactions.validateReceipt(application(),quote(),product(),r));}
 @Test void verifiedReceiptMustMatchTheLockedQuoteAndTerms(){assertDoesNotThrow(()->InsuranceTransactions.validateReceipt(application(),quote(),product(),receipt("app","order","CNY",new BigDecimal("8.50"),true)));var changed=quote();changed.put("terms_version","terms-v2");assertThrows(IllegalArgumentException.class,()->InsuranceTransactions.validateReceipt(application(),changed,product(),receipt("app","order","CNY",new BigDecimal("8.50"),true)));}
 @Test void credentialPrefixAndApiKeyAloneCannotEnableAnUnimplementedInsurer(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);when(guard.requireAdmin()).thenReturn("admin");var catalog=new InsuranceCatalog(new InsuranceStore(db,new ObjectMapper()),guard,List.of());var p=product();var input=new ProductInput(p.id(),p.insurerCode(),p.insurerName(),p.name(),p.kind(),p.adapter(),p.providerProductCode(),p.credentialPrefix(),p.termsUrl(),p.exclusionsUrl(),p.claimsUrl(),p.serviceHosts(),p.checkoutHosts(),true);assertThrows(IllegalStateException.class,()->catalog.save(input));verifyNoInteractions(db);}
 @Test void noRegisteredAdapterProducesNoPurchasableInsuranceProducts(){var db=mock(JdbcTemplate.class);var catalog=new InsuranceCatalog(new InsuranceStore(db,new ObjectMapper()),mock(DomainAccessGuard.class),List.of());assertTrue(catalog.products().isEmpty());assertTrue(InsurerDirectory.entries().size()>=10);assertTrue(InsurerDirectory.entries().stream().allMatch(row->row.get("status").equals("reference_only")));}
 @Test void externalDocumentsAndCheckoutCannotUseOtherHostsOrInsecureUrls(){for(String url:List.of("http://insurer.example/policy","https://other.example/policy","https://user@insurer.example/policy","https://insurer.example:8443/policy","https://insurer.example/policy#fragment"))assertThrows(IllegalArgumentException.class,()->InsuranceUrlPolicy.require(url,Set.of("insurer.example")));}
 @Test void anotherBuyersQuoteAndStaleQuoteCannotBeSelected(){var store=mock(InsuranceStore.class);var selections=new InsuranceSelections(store,mock(InsuranceCatalog.class));var q=new HashMap<String,Object>(Map.of("user_id","buyer","subject_type","trip","subject_id","trip","declared_value",new BigDecimal("1000"),"item_name","Camera","expires_at",Timestamp.from(Instant.now().minusSeconds(1))));when(store.quote("quote")).thenReturn(q);assertThrows(IllegalArgumentException.class,()->selections.validate("other","quote","trip","trip",new BigDecimal("1000"),"Camera"));assertThrows(IllegalArgumentException.class,()->selections.validate("buyer","quote","trip","trip",new BigDecimal("1000"),"Camera"));assertThrows(IllegalArgumentException.class,()->selections.validate("buyer",null,"trip","trip",new BigDecimal("1000"),"Camera"));}
 @Test void consentAndOwnOrderAreRequiredBeforeAnyProviderDispatch(){var db=mock(JdbcTemplate.class);var store=new InsuranceStore(db,new ObjectMapper());var tx=new InsuranceTransactions(store,mock(InsuranceCatalog.class),new ObjectMapper());assertThrows(IllegalArgumentException.class,()->tx.reserve("buyer",new ApplyInput("order","quote",UUID.randomUUID().toString(),false,true)));verifyNoInteractions(db);when(db.queryForList(anyString(),eq("order"))).thenReturn(List.of(Map.of("id","order","buyer_id","other")));assertThrows(IllegalArgumentException.class,()->tx.reserve("buyer",new ApplyInput("order","quote",UUID.randomUUID().toString(),true,true)));verify(db,never()).update(anyString(),any(Object[].class));}
 @Test void insurerApiHostRequiresBothProductAndEnvironmentAllowlist(){var p=product();assertThrows(IllegalArgumentException.class,()->InsuranceHttp.validate(p,java.net.URI.create("https://insurer.example/api"),Set.of()));assertThrows(IllegalArgumentException.class,()->InsuranceHttp.validate(p,java.net.URI.create("https://other.example/api"),Set.of("other.example")));assertDoesNotThrow(()->InsuranceHttp.validate(p,java.net.URI.create("https://insurer.example/api"),Set.of("insurer.example")));}

 @Test void aWebOnlyInsurerIsNotOfferedToTheMiniProgram() throws Exception {var db=mock(JdbcTemplate.class);var json=new ObjectMapper();var p=product();when(db.queryForList(anyString())).thenReturn(List.of(Map.of("config_json",json.writeValueAsString(p),"enabled",1,"revision",1)));var a=mock(Adapter.class);when(a.id()).thenReturn("native");when(a.insurerCode()).thenReturn("picc");when(a.configured(any())).thenReturn(true);when(a.supportedPlatforms(any())).thenReturn(Set.of("web"));var catalog=new InsuranceCatalog(new InsuranceStore(db,json),mock(DomainAccessGuard.class),List.of(a));assertTrue(catalog.products("mp_weixin").isEmpty());assertEquals(1,catalog.products("web").size());}

}
